@* Displays a single task card with title, assignee, priority badge, due date, and move buttons *@

<div class="card mb-2">
    <div class="card-body p-2">
        <h6 class="card-title mb-1">@Task.Title</h6>
        <p class="card-text mb-1 text-muted small">@Task.Assignee</p>
        <div class="d-flex justify-content-between align-items-center mb-1">
            <span class="badge @PriorityClass">@Task.Priority</span>
            <small class="text-muted">@Task.DueDate.ToString("MMM dd")</small>
        </div>
        <div class="d-flex justify-content-between">
            @if (ShowMoveLeft)
            {
                <button class="btn btn-outline-secondary btn-sm" @onclick="OnMoveLeftClick">← Move Left</button>
            }
            else
            {
                <span></span>
            }
            @if (ShowMoveRight)
            {
                <button class="btn btn-outline-secondary btn-sm" @onclick="OnMoveRightClick">Move Right →</button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async System.Threading.Tasks.Task OnMoveLeftClick() => await OnMoveLeft.InvokeAsync(Task.Id);
    private async System.Threading.Tasks.Task OnMoveRightClick() => await OnMoveRight.InvokeAsync(Task.Id);
}

@* Inline form for creating a new task within a column *@

@if (!IsVisible)
{
    <button class="btn btn-outline-primary btn-sm w-100" @onclick="Show">+ Add Task</button>
}
else
{
    <div class="card border-primary mt-2">
        <div class="card-body p-2">
            <div class="mb-2">
                <input type="text" class="form-control form-control-sm" placeholder="Title" @bind="_title" />
            </div>
            <div class="mb-2">
                <input type="text" class="form-control form-control-sm" placeholder="Assignee" @bind="_assignee" />
            </div>
            <div class="mb-2">
                <select class="form-select form-select-sm" @bind="_priority">
                    <option value="High">High</option>
                    <option value="Medium">Medium</option>
                    <option value="Low">Low</option>
                </select>
            </div>
            <div class="mb-2">
                <input type="date" class="form-control form-control-sm" @bind="_dueDate" />
            </div>
            <div class="d-flex gap-2">
                <button class="btn btn-primary btn-sm" @onclick="Save" disabled="@_saving">Save</button>
                <button class="btn btn-secondary btn-sm" @onclick="Cancel" disabled="@_saving">Cancel</button>
            </div>
            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="text-danger small mt-1">@_error</div>
            }
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }

    private bool IsVisible;
    private string _title = "";
    private string _assignee = "";
    private string _priority = "Medium";
    private DateTime _dueDate = DateTime.Today.AddDays(7);
    private bool _saving;
    private string? _error;

    private void Show() => IsVisible = true;

    private void Cancel()
    {
        IsVisible = false;
        ResetForm();
    }

    private void ResetForm()
    {
        _title = "";
        _assignee = "";
        _priority = "Medium";
        _dueDate = DateTime.Today.AddDays(7);
        _error = null;
    }

    private async System.Threading.Tasks.Task Save()
    {
        if (string.IsNullOrWhiteSpace(_title))
        {
            _error = "Title is required.";
            return;
        }

        _saving = true;
        _error = null;
        try
        {
            await OnTaskCreated.InvokeAsync(
                new TaskItem(0, _title.Trim(), _assignee.Trim(), _priority, _dueDate, Status));
            IsVisible = false;
            ResetForm();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

@* A single status column displaying its task cards and an add-task form *@

<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@Status</strong>
            <span class="badge bg-secondary rounded-pill">@Tasks.Count</span>
        </div>
        <div class="card-body p-2" style="overflow-y: auto; max-height: 70vh;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          ShowMoveLeft="ShowMoveLeft"
                          ShowMoveRight="ShowMoveRight"
                          OnMoveLeft="HandleMoveLeft"
                          OnMoveRight="HandleMoveRight" />
            }
            <AddTaskForm Status="@Status" OnTaskCreated="HandleTaskCreated" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<(int TaskId, string Direction)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }

    private async System.Threading.Tasks.Task HandleMoveLeft(int taskId)
        => await OnMoveTask.InvokeAsync((taskId, "left"));

    private async System.Threading.Tasks.Task HandleMoveRight(int taskId)
        => await OnMoveTask.InvokeAsync((taskId, "right"));

    private async System.Threading.Tasks.Task HandleTaskCreated(TaskItem task)
        => await OnTaskCreated.InvokeAsync(task);
}

@* Search input for filtering tasks by title *@

<div class="mb-3">
    <input type="text"
           class="form-control"
           placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="OnInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter] public EventCallback<string> OnSearchChanged { get; set; }

    private async System.Threading.Tasks.Task OnInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? "");
    }
}

@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger">
        <strong>Error loading tasks:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar Tasks="_allTasks" />
    <BoardSearchBar SearchText="@_searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="row g-3">
        @for (int i = 0; i < _statuses.Length; i++)
        {
            var status = _statuses[i];
            var columnTasks = FilteredTasks.Where(t => t.Status == status).ToList();
            <KanbanColumn Status="@status"
                          Tasks="columnTasks"
                          ShowMoveLeft="i > 0"
                          ShowMoveRight="i < _statuses.Length - 1"
                          OnMoveTask="HandleMoveTask"
                          OnTaskCreated="HandleTaskCreated" />
        }
    </div>
}

@code {
    private static readonly string[] _statuses = { "To Do", "In Progress", "Done" };

    private List<TaskItem> _allTasks = new();
    private string _searchText = "";
    private bool _loading = true;
    private string? _error;

    private List<TaskItem> FilteredTasks =>
        string.IsNullOrWhiteSpace(_searchText)
            ? _allTasks
            : _allTasks.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        _loading = true;
        _error = null;
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void HandleSearchChanged(string text)
    {
        _searchText = text;
    }

    private async Task HandleMoveTask((int TaskId, string Direction) args)
    {
        var task = _allTasks.FirstOrDefault(t => t.Id == args.TaskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(_statuses, task.Status);
        var newIndex = args.Direction == "left" ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= _statuses.Length) return;

        var newStatus = _statuses[newIndex];
        await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);

        // Update local state
        var idx = _allTasks.FindIndex(t => t.Id == task.Id);
        _allTasks[idx] = task with { Status = newStatus };
    }

    private async Task HandleTaskCreated(TaskItem placeholder)
    {
        var created = await TaskService.CreateTaskAsync(
            placeholder.Title, placeholder.Assignee, placeholder.Priority, placeholder.DueDate);
        _allTasks.Add(created);
    }
}

